  width: 64px;
  text-align: center;
  font-size: 24px;
  font-weight: 300;
  letter-spacing: -0.03em;
  white-space: nowrap;
}
.target.range {
  width: auto;
  min-height: 44px;
  padding: 0 14px;
  border-radius: 22px;
  font-size: 20px;
}
.flick {
  animation: lcFlick 2.4s ease-in-out infinite;
  transform-origin: 50% 90%;
}
@keyframes lcFlick {
  0%,
  100% {
    transform: scale(1) rotate(0);
  }
