    animation: none;
  }
  .press {
    transition: none;
  }
}

chrome.badge:
:host {
  display: inline-block;
  max-width: 100%;
}
.wrap {
  display: contents;
}
.g-dark {
  --lc-ring: #15171d;
}
.g-light {
  --lc-ring: #f3f4f7;
}
/* Sizes follow HA's own badge (ha-badge), through its theme tokens. */
.badge {
  --_size: var(--ha-badge-size, 36px);
  font: inherit;
  font-family: 'Inter', system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  font-feature-settings: 'tnum' 1;
  position: relative;
  box-sizing: border-box;
  height: var(--_size);
  min-width: var(--_size);
  margin: 0;
  display: flex;
  align-items: center;
  color: var(--lc-fg);
  background-color: var(--lc-bg);
  backdrop-filter: blur(var(--lc-blur, var(--_blur, 22px))) saturate(180%);
  -webkit-backdrop-filter: blur(var(--lc-blur, var(--_blur, 22px))) saturate(180%);
  border: 1px solid var(--lc-edge);
  border-radius: var(--ha-badge-border-radius, calc(var(--ha-badge-size, 36px) / 2));
  box-shadow:
    inset 0 1px 0 var(--lc-shine),
    0 12px 28px -14px rgba(0, 0, 0, 0.6);
  text-align: left;
}
button.badge {
  cursor: pointer;
}
button.badge:focus-visible {
  outline: 2px solid var(--lc-bright);
  outline-offset: 2px;
}
.pill {
  max-width: 100%;
  padding: 0 12px;
  gap: var(--ha-space-2, 8px);
}
.round {
  width: var(--_size);
  padding: 0;
  justify-content: center;
}
.ic {
  flex: none;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--lc-bright);
}
.ic svg {
  width: var(--ha-badge-icon-size, 18px);
  height: var(--ha-badge-icon-size, 18px);
}
/* The tinted circle sits 4px inside the badge edge, like HA pulls its icon in. */
.pill .ic {
  width: calc(var(--_size) - 8px);
  height: calc(var(--_size) - 8px);
  margin-inline-start: -8px;
  border-radius: 50%;
}
.txt {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.n {
  font-size: var(--ha-font-size-xs, 10px);
  font-weight: var(--ha-font-weight-medium, 500);
  line-height: 10px;
  letter-spacing: 0.1px;
  color: var(--lc-fg2);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.v {
  font-size: var(--ha-badge-font-size, var(--ha-font-size-s, 12px));
  font-weight: var(--ha-font-weight-medium, 500);
  line-height: var(--ha-line-height-condensed, 1.2);
  letter-spacing: 0.1px;
  white-space: nowrap;
}
.dot {
  position: absolute;
  right: 1px;
  top: 1px;
  width: 8px;
  height: 8px;
  box-sizing: content-box;
  border-radius: 50%;
  box-shadow: 0 0 0 2px var(--lc-ring);
  animation: lcDot 2.4s ease-in-out infinite;
}
@keyframes lcDot {
  0%,
  100% {
    opacity: 0.5;
    transform: scale(0.85);
  }
  50% {
    opacity: 1;
    transform: scale(1.1);
  }
}
.m-minimal .dot {
  animation: none;
}
@media (prefers-reduced-motion: reduce) {
  .dot {
    animation: none;
  }
}

chrome.cluster:
:host {
  display: block;
  container-type: inline-size;
}
.g-dark {
  --lc-room: rgba(255,255,255,0.04);
  --lc-room-on: rgba(100,140,240,0.1);
  --lc-room-edge: rgba(255,255,255,0.07);
  --lc-room-on-edge: rgba(255,255,255,0.26);
}
.g-light {
  --lc-room: rgba(255,255,255,0.55);
  --lc-room-on: rgba(255,255,255,0.7);
  --lc-room-edge: rgba(16,20,27,0.08);
  --lc-room-on-edge: rgba(16,20,27,0.3);
}
.cluster {
  font-family: 'Inter', system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  font-feature-settings: 'tnum' 1;
  position: relative;
  box-sizing: border-box;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  border-radius: var(--lc-radius, 36px);
  color: var(--lc-fg);
  background: var(--lc-bg);
  backdrop-filter: blur(var(--lc-blur, var(--_blur, 30px))) saturate(170%);
  -webkit-backdrop-filter: blur(var(--lc-blur, var(--_blur, 30px))) saturate(170%);
  border: 1px solid var(--lc-edge);
  box-shadow:
    inset 0 1px 0 var(--lc-shine),
    0 40px 80px -24px rgba(0, 0, 0, 0.65);
}
button {
  font: inherit;
  color: inherit;
  cursor: pointer;
  margin: 0;
  border: 1px solid var(--lc-btn-edge);
  background: var(--lc-btn);
}
button:focus-visible {
  outline: 2px solid var(--lc-bright);
  outline-offset: 2px;
}
button:disabled {
  cursor: default;
}
.press {
  transition:
    transform 0.3s cubic-bezier(0.3, 1.7, 0.5, 1),
    background-color 0.5s ease,
    border-color 0.5s ease;
}
.press:active:not(:disabled):not([aria-disabled='true']) {
  transform: scale(0.96);
}
header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 6px 16px;
  flex-wrap: wrap;
}
.title {
  display: flex;
  align-items: baseline;
  gap: 12px;
  min-width: 0;
}
h2 {
  margin: 0;
  font-size: 22px;
  font-weight: 600;
  letter-spacing: -0.02em;
}
.sum,
.figs {
  font-size: 13px;
  color: var(--lc-fg2);
}
.figs {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 22px;
}
.fig strong {
  font-weight: 500;
  color: var(--lc-fg);
}
.group {
  display: contents;
}
.floor {
  margin: 2px 0 -4px;
  font-size: 12px;
  font-weight: 500;
  color: var(--lc-fg2);
}
/* Narrow: compact rooms in a horizontal scroller. The vertical padding keeps focus rings unclipped. */
.rooms {
  display: flex;
  gap: 10px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  overscroll-behavior-x: contain;
  scrollbar-width: none;
  margin: -6px -16px;
  padding: 6px 16px;
  scroll-padding: 0 16px;
}
.rooms::-webkit-scrollbar {
  display: none;
}
.room {
  /* The next room peeks in, so the row reads as scrollable. */
  flex: 0 0 min(158px, 42cqw);
  scroll-snap-align: start;
  box-sizing: border-box;
  min-width: 0;
  border-radius: 22px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 4px;
  text-align: left;
  background: var(--lc-room);
  border-color: var(--lc-room-edge);
}
.room.sel {
  background: var(--lc-room-on);
  border-color: var(--lc-room-on-edge);
}
.rhead {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
.rname {
  font-size: 15px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.ricon {
  display: flex;
  flex: none;
}
.mini {
  position: relative;
  align-self: center;
  width: min(190px, 100%);
  aspect-ratio: 1;
  display: block;
}
.mini-svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  fill: none;
  stroke-linecap: round;
}
.track {
  stroke: var(--lc-track);
  stroke-width: 14;
}
.prog {
  stroke-width: 14;
}
.fan-dim {
  stroke: var(--lc-track);
  stroke-width: 10;
}
.fan-lit {
  stroke: var(--lc-bright);
  stroke-width: 10;
  opacity: 0.8;
}
.spin {
  stroke: var(--lc-tick);
  stroke-width: 2;
  stroke-dasharray: 2.4 14;
  transform-box: fill-box;
  transform-origin: center;
  animation: lcSpin 7s linear infinite;
}
.m-minimal .spin {
  animation: none;
}
@keyframes lcSpin {
  to {
    transform: rotate(360deg);
  }
}
.dot {
  fill: var(--lc-bright);
  stroke: none;
  opacity: 0.7;
}
.knob {
  fill: #ffffff;
  stroke-width: 6;
}
.center {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding-bottom: 4px;
}
.tline {
  display: flex;
  align-items: flex-start;
}
.big {
  font-size: 34px;
  font-weight: 200;
  letter-spacing: -0.04em;
  line-height: 1;
}
.tline.range .big {
  font-size: 18px;
  font-weight: 300;
}
.deg {
  font-size: 15px;
  font-weight: 300;
  margin-top: 3px;
  color: var(--lc-fg2);
}
.inside {
  font-size: 12px;
  color: var(--lc-fg2);
  margin-top: 6px;
  max-width: 100%;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.foot {
  font-size: 12px;
  color: var(--lc-fg3);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.foot.warn,
.sverb.warn {
  color: var(--lc-warn);
}
/* Error codes stay visible: up to two lines instead of an ellipsis. */
.foot.warn {
  white-space: normal;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
}
.empty {
  margin: 0;
  font-size: 13px;
  color: var(--lc-fg2);
}
/* Name and steppers on one row, the modes below; from 720px all on one row (see below). */
.strip {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-areas: 'who steps' 'modes modes';
  align-items: center;
  gap: 12px 16px;
  border-top: 1px solid var(--lc-line);
  padding-top: 14px;
}
.strip.nomodes {
  grid-template-areas: 'who steps';
}
.who {
  grid-area: who;
  min-width: 0;
  min-height: 44px;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 0 8px;
  margin-left: -8px;
  border: none;
  background: none;
  text-align: left;
  border-radius: 12px;
  transition: background-color 0.3s ease;
}
.who:hover,
.who:focus-visible {
  background: var(--lc-btn);
}
.wtext {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.chev {
  display: flex;
  flex: none;
  color: var(--lc-fg2);
}
.sname {
  font-size: 15px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.sverb {
  font-size: 12px;
  color: var(--lc-fg3);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.modes {
  grid-area: modes;
  min-width: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.mode {
  width: 44px;
  height: 44px;
  border-radius: 14px;
  padding: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}
.steps {
  grid-area: steps;
  display: flex;
  align-items: center;
  gap: 6px;
}
.step {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  padding: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}
/* aria-disabled, not disabled: the button keeps focus and _step ignores the click. */
.step[aria-disabled='true'] {
  opacity: 0.3;
  cursor: default;
}
.target {
  width: 66px;
  text-align: center;
  font-size: 24px;
  font-weight: 300;
  letter-spacing: -0.03em;
  white-space: nowrap;
}
.target.range {
  width: auto;
  min-height: 44px;
  padding: 0 14px;
  border-radius: 22px;
  font-size: 20px;
}
.sr {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}
/* Medium: two columns of full rooms. */
@container (min-width: 440px) {
  .cluster {
    padding: 20px;
  }
  .rooms {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px;
    overflow: visible;
    margin: 0;
    padding: 0;
  }
  .room {
    border-radius: 26px;
    padding: 14px;
  }
  .big {
    font-size: 40px;
  }
  .deg {
    font-size: 17px;
  }
  .tline.range .big {
    font-size: 22px;
  }
}
/* Wide: three columns, the strip on one row like the board; many modes wrap inside their cell. */
@container (min-width: 720px) {
  .cluster {
    padding: 24px;
    gap: 18px;
  }
  .rooms {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .room {
    padding: 16px;
  }
  .big {
    font-size: 44px;
  }
  .deg {
    font-size: 18px;
    margin-top: 4px;
  }
  .strip,
  .strip.nomodes {
    grid-template-columns: minmax(96px, 150px) minmax(0, 1fr) auto;
    grid-template-areas: 'who modes steps';
    padding-top: 16px;
  }
  .steps {
    gap: 8px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .spin {
    animation: none;
  }
  .press,
  .who {
    transition: none;
  }
}
